package com.crm.invoice.service;
import com.crm.security.AuthenticatedUserPrincipal;import org.springframework.security.core.context.SecurityContextHolder;import jakarta.validation.Validation;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
public final class InvoiceWorkAccess {private InvoiceWorkAccess(){}private static final jakarta.validation.Validator VALIDATOR=Validation.buildDefaultValidatorFactory().getValidator();public static long admin(){var a=SecurityContextHolder.getContext().getAuthentication();var p=AuthenticatedUserPrincipal.require(a);if(a.getAuthorities().stream().noneMatch(r->java.util.Set.of("ROLE_ADMIN","ROLE_SUPER_ADMIN").contains(r.getAuthority())))throw new org.springframework.security.access.AccessDeniedException("Administrative access required");return p.userId();}public static void valid(Object v){if(v==null||!VALIDATOR.validate(v).isEmpty())throw new IllegalArgumentException("Invalid invoice input");}public static long id(String v){if(v==null||!v.matches("[1-9][0-9]{0,18}"))throw new IllegalArgumentException("Canonical identifier required");try{return Long.parseLong(v);}catch(NumberFormatException e){throw new IllegalArgumentException("Identifier out of range");}}public static void uuid(String v){try{if(!java.util.UUID.fromString(v).toString().equals(v))throw new IllegalArgumentException();}catch(RuntimeException e){throw new IllegalArgumentException("Canonical UUID required");}}public static ResponseStatusException conflict(){return new ResponseStatusException(HttpStatus.CONFLICT,"Invoice state conflicts with operation");}public static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice resource unavailable");}public static org.springframework.data.domain.PageRequest page(int n){if(n<0)throw new IllegalArgumentException("Invalid page");return org.springframework.data.domain.PageRequest.of(n,20,org.springframework.data.domain.Sort.by("id").descending());}}
